import { app, Tray, nativeImage } from "electron";
import { join } from "node:path";
import type { TrayHostDeps, UsagePopupController } from "./usagePopup.js";

/**
 * macOS menu bar brand item — the dog-head silhouette (brand mark shared
 * with the Windows tray/titlebar; generated by gen-menubar-icons.mjs from
 * the tray ICO master) lives in the system menu bar's right-side status
 * area, entirely outside the app window.
 *
 * Left click routes by main-window state (closed → reopen the window via
 * deps.openMainWindow; open → toggle the usage popup). Right click always
 * toggles the popup (usagePopup.ts — CursorUsage-style subscription usage;
 * docs/plans/20261013-usage-popup-tray-icon.md). The former native menu
 * (New Task / Loops / Settings / Quit) is removed: the popup footer
 * carries Settings / Quit. No context menu is set, so both Tray click
 * events reach us.
 *
 * darwin-only: Windows keeps its resident tray (appTray.ts) untouched.
 */

/**
 * Renderer channel carrying a menu-bar quick action. Still consumed by
 * AppShellController — the usage popup footer reuses it for Settings.
 */
export const MENUBAR_ACTION_CHANNEL = "menubar:action";

export type MenubarAction = "new-task" | "loop" | "settings";

let tray: Tray | undefined;

/** `resources/menubar` — packaged under `process.resourcesPath`, dev next to app. */
function resolveMenubarDir(): string {
  const base = app.isPackaged
    ? process.resourcesPath
    : join(app.getAppPath(), "resources");
  return join(base, "menubar");
}

/**
 * Template PNG (pure black + alpha) with an explicit @2x representation so
 * Retina menu bars get the crisp raster instead of an upscale. Template
 * images are auto-inverted by macOS with the menu bar appearance.
 */
function loadTemplateImage(dir: string, name: string): Electron.NativeImage {
  const image = nativeImage.createFromPath(join(dir, `${name}.png`));
  const retina = nativeImage.createFromPath(join(dir, `${name}@2x.png`));
  if (!retina.isEmpty()) {
    image.addRepresentation({ scaleFactor: 2, buffer: retina.toBitmap() });
  }
  image.setTemplateImage(true);
  return image;
}

/**
 * Create the menu bar item. Returns true when the mark is live (safe
 * to call on any platform — non-darwin is a no-op false, mirroring
 * setupResidentTray's gate).
 */
export function setupMenuBarBrandItem(
  deps: TrayHostDeps,
  usagePopup: UsagePopupController,
): boolean {
  if (process.platform !== "darwin") return false;
  if (tray) return true;
  try {
    const dir = resolveMenubarDir();
    const dogHead = loadTemplateImage(dir, "dogHeadTemplate");
    if (dogHead.isEmpty()) {
      console.error("[menubar] dogHeadTemplate.png missing — no menu bar item");
      return false;
    }
    tray = new Tray(dogHead);
    tray.setToolTip("Larry Agent");
    // Click routing mirrors the Windows tray (appTray.ts). Tray.getBounds()
    // anchors the panel below the icon (usagePopupGeometry).
    tray.on("click", () => {
      if (!tray) return;
      if (!deps.isMainWindowOpen()) {
        deps.openMainWindow();
        return;
      }
      usagePopup.toggle(tray.getBounds());
    });
    tray.on("right-click", () => {
      if (!tray) return;
      usagePopup.toggle(tray.getBounds());
    });
    return true;
  } catch (err) {
    console.error("[menubar] create failed", err);
    tray = undefined;
    return false;
  }
}

